import{_ as e,o as t,c as r,af as l}from"./chunks/framework.D75dE8dq.js";const h=JSON.parse('{"title":"第1章 初识Trae IDE","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"pages/trae/01/01.md","filePath":"pages/trae/01/01.md","lastUpdated":null}'),o={name:"pages/trae/01/01.md"};function i(d,a,n,s,p,c){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="第1章-初识trae-ide" tabindex="-1">第1章 初识Trae IDE <a class="header-anchor" href="#第1章-初识trae-ide" aria-label="Permalink to &quot;第1章 初识Trae IDE&quot;">​</a></h1><h2 id="什么是trae" tabindex="-1">什么是Trae？ <a class="header-anchor" href="#什么是trae" aria-label="Permalink to &quot;什么是Trae？&quot;">​</a></h2><p>Trae（<code>/treɪ/</code>）IDE 与 AI 深度集成，提供智能问答、代码自动补全以及基于 Agent 的 AI 自动编程能力。</p><p>使用 Trae 开发项目时，你可以与 AI 灵活协作，提升开发效率。</p><h2 id="功能与亮点" tabindex="-1">功能与亮点 <a class="header-anchor" href="#功能与亮点" aria-label="Permalink to &quot;功能与亮点&quot;">​</a></h2><ol><li><p>完备的 IDE 功能 提供传统的 IDE 功能，包括代码编写、项目管理、插件管理、源代码管理等。</p></li><li><p>强大的 AI 助手 - 智能问答 在编写代码时，你可以随时与 AI 助手对话，获得代码解释、代码注释和错误修复等帮助。</p><ul><li>实时代码建议 AI 助手能够理解当前代码并在编辑器中实时提供代码建议，提升编程效率。</li><li>代码片段生成 通过自然语言描述你的需求，AI 助手将生成相应的代码片段，甚至能够编写项目级或跨文件的代码。</li><li>从 0 到 1 开发项目 告诉 AI 助手你想开发的程序，AI 助手将根据你的描述提供相关代码或自动创建所需文件。</li></ul></li></ol>',6)])])}const I=e(o,[["render",i]]);export{h as __pageData,I as default};
